import { execFileSync } from 'node:child_process'
import { lstatSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { parseArgs } from 'node:util'

// Codemod behind the P0-04 scope rename: rewrites the old package scope to `@nymbalhq/` in every git-tracked text
// file under --root. It is the record of the rename and is idempotent: the new scope does not contain the old one,
// so a second run finds nothing to change. pnpm-lock.yaml is regenerated by `pnpm install`, and archive/ is history.
//
//   pnpm exec tsx scripts/rename-scope.ts --root <dir>

// The old scope is assembled so this file does not name it literally (the repository scan for stragglers reads it).
const OLD_SCOPE = ['@nymbal', '/'].join('')
const NEW_SCOPE = '@nymbalhq/'

const SKIPPED = (file: string): boolean => file.startsWith('archive/') || file === 'pnpm-lock.yaml'

function trackedFiles(root: string): string[] {
  return execFileSync('git', ['ls-files', '-z'], {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  })
    .split('\0')
    .filter((file) => file.length > 0 && !SKIPPED(file))
}

/** Rewrites one file; returns the number of occurrences replaced (0 for symlinks, binary files and misses). */
function renameIn(path: string): number {
  // Symlinks and gitlinks are not rewritten: their targets are tracked paths of their own.
  if (!lstatSync(path).isFile()) return 0
  const bytes = readFileSync(path)
  if (bytes.includes(0) || !bytes.includes(OLD_SCOPE)) return 0
  const text = bytes.toString('utf8')
  // Not valid UTF-8: rewriting would corrupt it.
  if (!Buffer.from(text, 'utf8').equals(bytes)) return 0
  const count = text.split(OLD_SCOPE).length - 1
  writeFileSync(path, text.replaceAll(OLD_SCOPE, NEW_SCOPE))
  return count
}

function main(): void {
  const { values } = parseArgs({ options: { root: { type: 'string', default: '.' } } })
  const root = resolve(values.root)
  let files = 0
  let occurrences = 0
  for (const file of trackedFiles(root)) {
    let count: number
    try {
      count = renameIn(join(root, file))
    } catch {
      // Tracked but deleted in the working tree: nothing to rewrite.
      continue
    }
    if (count === 0) continue
    files += 1
    occurrences += count
  }
  console.log(`rename-scope: ${occurrences} occurrences rewritten in ${files} files under ${root}`)
}

main()
